import React, { Component } from 'react';
import './nav.css';

class Nav extends Component {

    render() {  
        var leftElement;
        if (!this.props.showHomeButton)
            leftElement = "";
        else
            leftElement = <a href="/"><i className="fas fa-home"></i>Home</a>;
        return (
        <div className="nav">

            <div className="single-link">
            {leftElement}
            </div>
            <div className="link-box">
                <div className="link">
                    <a href="https://github.com/tanayv"><i className="fab fa-github"></i>GitHub</a>
                </div>
                <div className="link">
                    <a href="https://dribbble.com/tanayv1"><i className="fab fa-dribbble"></i>Dribbble</a>
                </div>
            </div>
        </div>
        );
    }
  }
  
  export default Nav;